-- =====================================================================
-- GAARD Capital CRM · db/012 tests (Events, Event attendees, RFPs)
--
-- Builds upload tables shaped like Jon's Event ROI Tracker and RFP Log (and
-- two generic sheets), runs them through import_gaard_tab(), and checks what
-- lands. Everything rolls back, so it is safe on a database with data in it:
--     psql "$DATABASE_URL" -f db/tests/events_rfps_test.sql
-- The upload tables are generated by db/scripts/events_rfps_fixtures.py.
-- =====================================================================
\set QUIET on
\pset pager off
begin;

create temp table test_results (n serial primary key, test text, ok boolean, detail text) on commit drop;
create function pg_temp.ok(p boolean, p_test text, p_detail text default null) returns void
language plpgsql as $$
begin
  insert into test_results (test, ok, detail) values (p_test, coalesce(p, false), p_detail);
end $$;

-- upload tables, as Supabase's CSV import would create them
-- generated by tests/events_rfps_fixtures.py
set client_min_messages to warning;
drop table if exists upload_events; create table upload_events (id bigint generated by default as identity, "Event" text, "Date" text, "Type" text, "In Person / Virtual" text, "Host" text, "Location" text, "Cost" text, "Attendees" text, "Contacts Made" text, "Who Attended" text, "Notes" text, "Worth it?" text);
insert into upload_events ("Event", "Date", "Type", "In Person / Virtual", "Host", "Location", "Cost", "Attendees", "Contacts Made", "Who Attended", "Notes", "Worth it?") values ('Utah Nonprofits Association Conference', 'Oct 3-5, 2025', 'Conference', 'In person', 'Utah Nonprofits Association', 'Salt Lake City, UT', '$1,250', '400', '18', 'Test Owner', 'Good turnout, sponsor table', 'Yes');
insert into upload_events ("Event", "Date", "Type", "In Person / Virtual", "Host", "Location", "Cost", "Attendees", "Contacts Made", "Who Attended", "Notes", "Worth it?") values ('Community Foundation Roundtable', '11/12/2025', 'Roundtable', 'Virtual', 'Philanthropy West', 'Zoom', '0', '35', '6', null, 'Follow up with the moderator', null);
insert into upload_events ("Event", "Date", "Type", "In Person / Virtual", "Host", "Location", "Cost", "Attendees", "Contacts Made", "Who Attended", "Notes", "Worth it?") values ('Idaho Business Benefits Workshop', '2/20/26 - 2/21/26', 'Workshop', null, 'Boise Chamber', 'Boise, ID', '$300', '60', null, 'Test Teammate', null, 'Maybe');
insert into upload_events ("Event", "Date", "Type", "In Person / Virtual", "Host", "Location", "Cost", "Attendees", "Contacts Made", "Who Attended", "Notes", "Worth it?") values ('Utah Nonprofits Association Conference', '10/3/25', 'Conference', 'In person', null, 'Salt Lake City, UT', null, null, null, null, 'Same event again, second row in the sheet', null);
insert into upload_events ("Event", "Date", "Type", "In Person / Virtual", "Host", "Location", "Cost", "Attendees", "Contacts Made", "Who Attended", "Notes", "Worth it?") values (null, '1/1/26', null, null, null, null, null, null, null, null, 'a row with no name', null);
drop table if exists upload_event_attendees; create table upload_event_attendees (id bigint generated by default as identity, "Event" text, "Date" text, "Contact" text, "First Name" text, "Email" text, "Organization" text, "Website" text, "Notes" text, "Outcome" text, "Next Steps" text);
insert into upload_event_attendees ("Event", "Date", "Contact", "First Name", "Email", "Organization", "Website", "Notes", "Outcome", "Next Steps") values ('Utah Nonprofits Association Conference', '10/4/25', 'Grace Holt', 'Grace', 'grace@brightpath.example', 'BrightPath Youth Services', 'brightpath.example', 'Sat at our table', 'Had a meeting at the event', 'Send deck');
insert into upload_event_attendees ("Event", "Date", "Contact", "First Name", "Email", "Organization", "Website", "Notes", "Outcome", "Next Steps") values ('Utah Nonprofits Association Conference', '10/4/25', 'Omar Haddad', 'Omar', 'omar@desertarts.example', 'Desert Arts Council', 'desertarts.example', null, 'Met at event, exchanged info', null);
insert into upload_event_attendees ("Event", "Date", "Contact", "First Name", "Email", "Organization", "Website", "Notes", "Outcome", "Next Steps") values ('Community Foundation Roundtable', '11/12/25', 'Chris Dole', 'Chris', 'cdole@peakcf.example', 'Peak Community Foundation', 'peakcf.example', 'Moderator', 'Met at event, exchanged info', 'Email next week');
insert into upload_event_attendees ("Event", "Date", "Contact", "First Name", "Email", "Organization", "Website", "Notes", "Outcome", "Next Steps") values ('Utah Nonprofits Association Conference', '10/5/25', 'Nina Park', 'Nina', 'nina@riversidearts.example', 'Riverside Arts Alliance', 'riversidearts.example', 'New lead', 'Interested, call scheduled', 'Call 10/15');
drop table if exists upload_rfps; create table upload_rfps (id bigint generated by default as identity, "Organization" text, "Contact" text, "Email" text, "RFP" text, "Type" text, "Source" text, "Estimated AUM" text, "Date Released" text, "Due Date" text, "Submitted" text, "Status" text, "Decision Date" text, "Notes" text);
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values ('Peak Community Foundation', 'Chris Dole', 'cdole@peakcf.example', 'OCIO services 2026', 'OCIO', 'Consultant', '$40M', '1/15/26', '3/1/26', '2/25/26', 'Finalist', null, 'Presentation 3/20');
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values ('Grand Foundation', 'Rob Steele', 'rob@grandfdn.example', 'Investment consulting RFP', 'Investment consulting', 'RFP database', '$25M', '9/1/25', '10/15/25', '10/10/25', 'Lost', '12/1/25', 'Went with incumbent');
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values ('Harbor Literacy Project', null, null, 'Endowment management', 'OCIO', 'Direct invitation', '$1.1M', '3/1/26', '4/15/26', null, 'Intent to bid', null, null);
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values ('Cedar Clinic Foundation', 'Leo Brandt', 'leo@cedarclinic.example', 'OCIO mandate', 'OCIO', 'Consultant', '$2M', '2/1/25', '4/1/25', '3/28/25', 'Won', '5/15/25', 'Funded');
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values ('New Horizons Trust', 'Pat Lee', 'pat@newhorizonstrust.example', '401(k) advisor search', '401(k) plan advisor', 'Benefit broker', '$3.5M', '5/1/26', '6/30/26', null, 'Watching', null, 'Due next summer');
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values ('Mystery Foundation', null, null, 'Something', null, null, null, null, null, null, 'Banana', null, 'status nobody understands');
insert into upload_rfps ("Organization", "Contact", "Email", "RFP", "Type", "Source", "Estimated AUM", "Date Released", "Due Date", "Submitted", "Status", "Decision Date", "Notes") values (null, null, null, 'No org row', null, null, null, null, null, null, null, null, null);
drop table if exists upload_event_tracker; create table upload_event_tracker (id bigint generated by default as identity, "Date" text, "Cost" text, "Event Name" text, "Event Type" text, "State" text, "# of Contacts" text, "# of Responses" text, "# of Meetings" text, "Clients Won ($)" text, "Notes" text);
insert into upload_event_tracker ("Date", "Cost", "Event Name", "Event Type", "State", "# of Contacts", "# of Responses", "# of Meetings", "Clients Won ($)", "Notes") values ('3/12/2026', '$2,500', 'Utah Philanthropy Day', 'Conference', 'UT', '22', '6', '3', '$1,500,000', 'Sponsor booth');
insert into upload_event_tracker ("Date", "Cost", "Event Name", "Event Type", "State", "# of Contacts", "# of Responses", "# of Meetings", "Clients Won ($)", "Notes") values ('4/8/2026', '$150', 'Boise Nonprofit Lunch & Learn', 'Networking', 'ID', '9', '2', '1', null, null);
insert into upload_event_tracker ("Date", "Cost", "Event Name", "Event Type", "State", "# of Contacts", "# of Responses", "# of Meetings", "Clients Won ($)", "Notes") values ('5/20/2026', '0', 'Endowment 101 Webinar', 'Webinar', null, '40', '5', '2', '$0', 'GAARD hosted');
drop table if exists upload_rfp_log; create table upload_rfp_log (id bigint generated by default as identity, "RFP Name / Issuer" text, "RFP Reference Number" text, "Final Submission Date" text, "Approved for Submission (Y/N)" text, "Reviewed By" text, "Date Reviewed" text, "Size of AUM" text, "Conditions or Limitations" text, "Notes" text, "Response" text, "Date Responded" text, "Correspondence" text, "WON" text);
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Investment Advisory Services RFP / Mountain West Arts Foundation', 'RFP-2026-014', '2026-02-15', 'Y', 'Test Owner', '2026-02-10', '$12,000,000', 'Must be registered in UT', 'Sent via portal', 'Shortlisted, finalist presentation 3/20', '2026-03-02', 'Emails with the CFO', null);
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Cedar Valley Community Foundation / OCIO Search', null, '2025-11-30', 'Y', 'Test Teammate', '2025-11-20', '$3.5M', null, null, 'Not selected', '2026-01-15', null, 'N');
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Harbor Literacy Project', 'HLP-01', '2026-12-01', 'Y', 'Test Owner', '2026-10-01', '$1.1M', null, null, null, null, null, null);
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Public Pension RFQ / Big County', 'BC-77', '2026-01-10', 'N', 'Test Owner', '2026-01-05', '$900M', 'Minimum $500M AUM manager', 'Too large for us', null, null, null, null);
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Retirement Plan Advisor Search / Peak Community Foundation', null, '2026-03-01', 'Y', 'Test Owner', '2026-02-20', '$2M', null, null, 'Thanks, we will review and get back to you', '2026-03-05', null, null);
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Endowment Management / Grand Foundation', 'GF-2025', '2025-06-30', 'Y', 'Test Teammate', '2025-06-25', '$25M', null, null, 'Awarded', '2025-08-01', null, 'Y');
insert into upload_rfp_log ("RFP Name / Issuer", "RFP Reference Number", "Final Submission Date", "Approved for Submission (Y/N)", "Reviewed By", "Date Reviewed", "Size of AUM", "Conditions or Limitations", "Notes", "Response", "Date Responded", "Correspondence", "WON") values ('Investment Advisory Services RFP / Mountain West Arts Foundation', 'RFP-2026-014', null, null, null, null, null, null, 'Second row for the same RFP', null, null, null, null);


do $t$
declare
  j      jsonb;
  v_ev   events;
  v_n    int;
  v_c    contacts;
  v_r    rfps;
  d      record;
begin
  insert into team_members (id, full_name, email, role)
  values (1, 'Test Owner', 'owner@test.example', 'founder'), (2, 'Test Teammate', 'teammate@test.example', 'analyst')
  on conflict (id) do update set full_name = excluded.full_name;   -- rolled back with everything else

  -- date ranges -------------------------------------------------------------------------------------
  select * into d from parse_date_range('Oct 3-5, 2025');
  perform pg_temp.ok(d.start_on = '2025-10-03' and d.end_on = '2025-10-05', '"Oct 3-5, 2025" -> Oct 3 to Oct 5');
  select * into d from parse_date_range('2/20/26 - 2/21/26');
  perform pg_temp.ok(d.start_on = '2026-02-20' and d.end_on = '2026-02-21', '"2/20/26 - 2/21/26" -> both dates');
  select * into d from parse_date_range('10/3-10/5/2025');
  perform pg_temp.ok(d.start_on = '2025-10-03' and d.end_on = '2025-10-05', '"10/3-10/5/2025" -> the year applies to both');
  select * into d from parse_date_range('November 12, 2025');
  perform pg_temp.ok(d.start_on = '2025-11-12' and d.end_on = '2025-11-12', '"November 12, 2025" -> one day');
  select * into d from parse_date_range('sometime in fall');
  perform pg_temp.ok(d.start_on is null, 'Unreadable date -> null, not an error');
  perform pg_temp.ok(parse_loose_date('11/20/205') is null and parse_loose_date('11/20/2025') = '2025-11-20',
                     'A three-digit year is still refused (006), a normal one read');

  -- Events sheet ------------------------------------------------------------------------------------
  select count(*) into v_n from check_upload_headers('upload_events', 'Events') where maps_to is null and column_name <> 'id';
  perform pg_temp.ok(v_n = 0, 'Events: every header recognized by the dry run', v_n || ' unrecognized');
  j := import_gaard_tab('upload_events', 'Events');
  perform pg_temp.ok((j->>'events_created')::int = 3 and (j->>'events_already_there')::int = 1
                     and jsonb_array_length(j->'skipped') = 1,
                     'Events: 3 created, the repeated conference merged, the nameless row skipped with its row number', j::text);
  select * into v_ev from events where name = 'Utah Nonprofits Association Conference';
  perform pg_temp.ok(v_ev.event_type = 'conference' and v_ev.format = 'in_person' and v_ev.start_on = '2025-10-03'
                     and v_ev.end_on = '2025-10-05' and v_ev.city = 'Salt Lake City' and v_ev.state = 'UT'
                     and v_ev.cost_usd = 1250 and v_ev.attendees_est = 400 and v_ev.people_met_reported = 18
                     and v_ev.owner_id = 1 and v_ev.host_org = 'Utah Nonprofits Association'
                     and v_ev.notes like '%Worth it?: Yes%' and v_ev.notes like '%Same event again%',
                     'Conference row: type, format, date range, city/state from "Salt Lake City, UT", $ cost, counts, owner by name, extra column kept in notes');
  select * into v_ev from events where name = 'Community Foundation Roundtable';
  perform pg_temp.ok(v_ev.event_type = 'networking' and v_ev.format = 'virtual' and v_ev.city = 'Zoom' and v_ev.cost_usd = 0,
                     'Roundtable on Zoom -> networking, virtual');
  select * into v_ev from events where name = 'Idaho Business Benefits Workshop';
  perform pg_temp.ok(v_ev.event_type = 'workshop' and v_ev.format = 'in_person' and v_ev.state = 'ID' and v_ev.owner_id = 2
                     and v_ev.end_on = '2026-02-21',
                     'Workshop with a two-date range and a teammate name');

  -- Event attendees ----------------------------------------------------------------------------------
  select count(*) into v_n from check_upload_headers('upload_event_attendees', 'Event attendees') where maps_to is null and column_name <> 'id';
  perform pg_temp.ok(v_n = 0, 'Event attendees: every header recognized', v_n || ' unrecognized');
  j := import_gaard_tab('upload_event_attendees', 'Event attendees');
  perform pg_temp.ok((j->>'rows')::int = 4 and (j->>'errors')::int = 0, 'Event attendees import ran without errors', j::text);
  select * into v_c from contacts where email_key = 'nina@riversidearts.example';
  select * into v_ev from events where name = 'Utah Nonprofits Association Conference';
  perform pg_temp.ok(v_c.source_channel_code = 'EVENT' and v_c.source_event_id = v_ev.id
                     and exists (select 1 from touchpoints t where t.contact_id = v_c.id and t.touch_type = 'event'
                                   and t.event_id = v_ev.id and t.direction = 'in_person' and t.outcome_code = 'INTERESTED'
                                   and t.outcome_status = 'confirmed' and t.touched_at::date = '2025-10-05'),
                     'A new person met at the conference: EVENT channel, tied to the event by name, in-person touch on the sheet''s date, interested');
  select * into v_c from contacts where email_key = 'grace@brightpath.example';
  perform pg_temp.ok(exists (select 1 from touchpoints t where t.contact_id = v_c.id and t.outcome_code = 'MEETING_AT_EVENT' and t.outcome_status = 'confirmed'),
                     '"Had a meeting at the event" recognized');
  -- an outcome the aliases only half understand: met is the fact, the rest is a suggestion for a person
  insert into upload_event_attendees ("Event", "Date", "Contact", "Email", "Organization", "Outcome")
  values ('Utah Nonprofits Association Conference', '10/4/25', 'Sam Vague', 'sam@vague.example', 'Vague Org', 'Seemed interested, call scheduled maybe?');
  j := import_gaard_tab('upload_event_attendees', 'Event attendees');
  select * into v_c from contacts where email_key = 'sam@vague.example';
  perform pg_temp.ok((j->>'new_contacts')::int = 1 and exists (select 1 from touchpoints t where t.contact_id = v_c.id and t.touch_type = 'event'
                                   and t.outcome_code = 'MET_AT_EVENT' and t.outcome_status = 'needs_review' and t.ai_suggested_outcome = 'INTERESTED'),
                     'Half-understood outcome at an event: logged as met, suggestion "interested" waits in the review queue; re-run touches nothing else', j::text);
  select * into v_c from contacts where email_key = 'cdole@peakcf.example';
  select * into v_ev from events where name = 'Community Foundation Roundtable';
  perform pg_temp.ok(exists (select 1 from touchpoints t where t.contact_id = v_c.id and t.event_id = v_ev.id
                               and t.touch_type = 'event' and t.direction = 'outbound' and t.outcome_code = 'MET_AT_EVENT'),
                     'Virtual event -> the touch is not marked in person; "Met at event, exchanged info" recognized');
  perform pg_temp.ok((select people_met from v_event_performance where name = 'Utah Nonprofits Association Conference') = 4
                     and (select cost_per_person_met from v_event_performance where name = 'Utah Nonprofits Association Conference') = round(1250.0 / 4, 2),
                     'v_event_performance counts the four people entered by name for the conference');
  perform pg_temp.ok((select cost_per_person_met from v_event_performance where name = 'Idaho Business Benefits Workshop') is null
                     and (select people_met_reported from v_event_performance where name = 'Utah Nonprofits Association Conference') = 18,
                     'The sheet''s own people-met count is kept alongside');

  -- RFPs ----------------------------------------------------------------------------------------------
  select count(*) into v_n from check_upload_headers('upload_rfps', 'RFPs') where maps_to is null and column_name <> 'id';
  perform pg_temp.ok(v_n = 0, 'RFPs: every header recognized', v_n || ' unrecognized');
  j := import_gaard_tab('upload_rfps', 'RFPs');
  perform pg_temp.ok((j->>'rfps_created')::int = 5 and jsonb_array_length(j->'skipped') = 2
                     and (j->>'organizations_created')::int >= 1 and (j->>'contacts_created')::int >= 1,
                     'RFPs: 5 created; the unknown status and the empty organization are skipped with reasons', j::text);
  select * into v_r from rfps where title = 'OCIO services 2026';
  perform pg_temp.ok(v_r.status = 'finalist' and v_r.est_mandate_aum = 40000000 and v_r.due_on = '2026-03-01'
                     and v_r.submitted_on = '2026-02-25' and v_r.mandate_type = 'OCIO' and v_r.found_via = 'Consultant'
                     and v_r.contact_id = (select id from contacts where email_key = 'cdole@peakcf.example')
                     and exists (select 1 from touchpoints t where t.rfp_id = v_r.id and t.outcome_code = 'RFP_FINALIST'),
                     'Finalist RFP: dates, $40M, matched to the existing contact, finalist touch logged');
  select * into v_r from rfps where title = 'OCIO mandate';
  perform pg_temp.ok(v_r.status = 'won' and v_r.decision_on = '2025-05-15'
                     and exists (select 1 from touchpoints t where t.rfp_id = v_r.id and t.outcome_code = 'RFP_WON'),
                     'Won RFP: decision date and a won touch');
  select * into v_r from rfps where title = 'Investment consulting RFP';
  perform pg_temp.ok(v_r.status = 'lost' and exists (select 1 from touchpoints t where t.rfp_id = v_r.id and t.outcome_code = 'RFP_LOST'),
                     'Lost RFP logged');
  select * into v_r from rfps where title = 'Endowment management';
  perform pg_temp.ok(v_r.status = 'intent_to_bid' and v_r.contact_id is null
                     and v_r.organization_id = (select id from organizations where name = 'Harbor Literacy Project')
                     and exists (select 1 from reminders r where r.rfp_id = v_r.id and r.reminder_type = 'rfp_deadline' and r.due_on = date '2026-04-15' - 7),
                     'Open RFP without a contact: matched to the organization, due-date reminder a week ahead');
  select * into v_r from rfps where title = '401(k) advisor search';
  perform pg_temp.ok(v_r.status = 'identified' and exists (select 1 from organizations where name = 'New Horizons Trust')
                     and exists (select 1 from contacts where email_key = 'pat@newhorizonstrust.example' and source_channel_code = 'RFP'),
                     '"Watching" -> identified; new organization and contact created with RFP as the channel');
  perform pg_temp.ok((select count(*) from v_rfp_tracker where organization in ('Peak Community Foundation', 'Grand Foundation', 'Harbor Literacy Project', 'Cedar Clinic Foundation', 'New Horizons Trust')) = 5,
                     'v_rfp_tracker lists all five');

  -- Jon's Event ROI Tracker (headers exactly as in his template) --------------------------------------
  select count(*) into v_n from check_upload_headers('upload_event_tracker', 'Events') where maps_to is null and column_name <> 'id';
  perform pg_temp.ok(v_n = 0, 'Event ROI Tracker: every header recognized (# of Contacts / Responses / Meetings, Clients Won ($))', v_n || ' unrecognized');
  j := import_gaard_tab('upload_event_tracker', 'Events');
  perform pg_temp.ok((j->>'events_created')::int = 3 and jsonb_array_length(j->'skipped') = 0, 'Event ROI Tracker: 3 events created', j::text);
  select * into v_ev from events where name = 'Utah Philanthropy Day';
  perform pg_temp.ok(v_ev.event_type = 'conference' and v_ev.state = 'UT' and v_ev.start_on = '2026-03-12' and v_ev.cost_usd = 2500
                     and v_ev.people_met_reported = 22 and v_ev.responses_reported = 6 and v_ev.meetings_reported = 3
                     and v_ev.clients_won_usd = 1500000 and v_ev.format = 'in_person',
                     'Tracker row: date, $ cost, state, the four counts');
  select * into v_ev from events where name = 'Endowment 101 Webinar';
  perform pg_temp.ok(v_ev.format = 'virtual' and v_ev.event_type = 'webinar' and v_ev.cost_usd = 0 and v_ev.clients_won_usd = 0,
                     'Webinar row: virtual, zero cost and zero won are kept as zero');
  perform pg_temp.ok((select cost_per_person_met from v_event_performance where name = 'Utah Philanthropy Day') = round(2500.0 / 22, 2)
                     and (select cost_per_call from v_event_performance where name = 'Utah Philanthropy Day') = round(2500.0 / 3, 2)
                     and (select cost_per_response from v_event_performance where name = 'Utah Philanthropy Day') = round(2500.0 / 6, 2)
                     and (select won_per_dollar_spent from v_event_performance where name = 'Utah Philanthropy Day') = 600.0,
                     'v_event_performance: cost per contact / response / meeting and won per dollar from the sheet''s counts');

  -- Jon's RFP Log ---------------------------------------------------------------------------------------
  select count(*) into v_n from check_upload_headers('upload_rfp_log', 'RFPs') where maps_to is null and column_name <> 'id';
  perform pg_temp.ok(v_n = 0, 'RFP Log: every header recognized', v_n || ' unrecognized');
  j := import_gaard_tab('upload_rfp_log', 'RFPs');
  perform pg_temp.ok((j->>'rfps_created')::int = 6 and (j->>'rfps_already_there')::int = 1 and jsonb_array_length(j->'skipped') = 0
                     and jsonb_array_length(j->'responses_to_check') = 1 and (j->'responses_to_check'->0->>'row')::int = 6,
                     'RFP Log: 6 RFPs, the repeated reference number merged, one response flagged for a person', j::text);
  select * into v_r from rfps where reference_number = 'RFP-2026-014';
  perform pg_temp.ok(v_r.title = 'Investment Advisory Services RFP' and v_r.status = 'finalist' and v_r.due_on = '2026-02-15'
                     and v_r.submitted_on = '2026-02-15' and v_r.approved_for_submission and v_r.reviewed_by = 'Test Owner' and v_r.owner_id = 1
                     and v_r.reviewed_on = '2026-02-10' and v_r.est_mandate_aum = 12000000 and v_r.terms = 'Must be registered in UT'
                     and v_r.decision_notes like 'Response: Shortlisted%' and v_r.decision_notes like '%Emails with the CFO%' and v_r.decision_on = '2026-03-02'
                     and v_r.notes like '%Second row for the same RFP%' and v_r.decision_result is null
                     and v_r.organization_id = (select id from organizations where name = 'Mountain West Arts Foundation'),
                     '"Name / Issuer" split, finalist from the Response wording, approved + past date = submitted, reviewer, conditions, correspondence');
  select * into v_r from rfps where organization_id = (select id from organizations where name = 'Cedar Valley Community Foundation');
  perform pg_temp.ok(v_r.title = 'OCIO Search' and v_r.status = 'lost' and v_r.decision_on = '2026-01-15' and v_r.decision_result = 'not_awarded',
                     'Issuer written first: still split the right way; WON = N with a response = lost');
  select * into v_r from rfps where reference_number = 'HLP-01';
  perform pg_temp.ok(v_r.status = 'intent_to_bid' and v_r.title like 'RFP: Harbor Literacy Project%'
                     and v_r.organization_id = (select id from organizations where name = 'Harbor Literacy Project')
                     and exists (select 1 from reminders r where r.rfp_id = v_r.id and r.reminder_type = 'rfp_deadline' and r.status = 'open'),
                     'Issuer only, approved, due in the future: intent to bid with a deadline reminder, matched to the known organization');
  select * into v_r from rfps where reference_number = 'BC-77';
  perform pg_temp.ok(v_r.status = 'declined' and v_r.approved_for_submission = false and v_r.est_mandate_aum = 900000000,
                     'Reviewed and not approved = declined; $900M read');
  select * into v_r from rfps where title = 'Retirement Plan Advisor Search';
  perform pg_temp.ok(v_r.status = 'submitted' and v_r.decision_notes like 'Response: Thanks%'
                     and v_r.organization_id = (select id from organizations where name = 'Peak Community Foundation'),
                     'A reply nobody can read as a status: submitted, text kept, flagged');
  select * into v_r from rfps where reference_number = 'GF-2025';
  perform pg_temp.ok(v_r.status = 'won' and v_r.decision_on = '2025-08-01' and v_r.decision_result = 'awarded'
                     and v_r.organization_id = (select id from organizations where name = 'Grand Foundation'),
                     'WON = Y -> won, matched to the existing organization');
  perform pg_temp.ok((select count(*) from v_rfp_tracker where reference_number is not null) >= 4
                     and (select reviewed_by from v_rfp_tracker where reference_number = 'RFP-2026-014') = 'Test Owner',
                     'v_rfp_tracker shows the log''s columns');
  j := import_gaard_tab('upload_rfp_log', 'RFPs');
  perform pg_temp.ok((j->>'rfps_created')::int = 0, 'RFP Log twice: nothing duplicated');

  -- running the sheets again changes nothing ------------------------------------------------------------
  select count(*) into v_n from events;
  j := import_gaard_tab('upload_events', 'Events');
  perform pg_temp.ok((select count(*) from events) = v_n and (j->>'events_created')::int = 0, 'Events sheet twice: no duplicates');
  select count(*) into v_n from rfps;
  j := import_gaard_tab('upload_rfps', 'RFPs');
  perform pg_temp.ok((select count(*) from rfps) = v_n and (j->>'rfps_created')::int = 0
                     and (select count(*) from touchpoints where touch_type = 'rfp' and rfp_id in (select id from rfps)) >= 3,
                     'RFP sheet twice: no duplicate RFPs or touches');
end $t$;

select n, case when ok then 'PASS' else 'FAIL' end as result, test, left(detail, 110) as detail from test_results order by n;
select count(*) filter (where ok) as passed, count(*) filter (where not ok) as failed from test_results;
rollback;
